  function jobProgress(job){const number=Number(job.progress);return Number.isFinite(number)?Math.max(0,Math.min(100,number)):0;}
  function renderJobs(){$("jobs-panel").hidden=!state.jobs.length;$("jobs-list").replaceChildren(...state.jobs.map(job=>{const row=node("article",null,"job-row");const main=node("div",null,"row-main");main.append(node("h3",job.policy_title||job.title||job.original_name||job.filename||state.policies.find(policy=>policy.id===job.policy_id)?.title||t("jobLabel",{id:job.id.slice(0,8)})));const meta=node("div",null,"row-meta");meta.append(badge(job.status),node("span",stageLabel(job.stage)),node("span",time(job.created_at)));main.append(meta);if(!finished(job.status)){const p=node("progress");p.max=100;p.value=jobProgress(job);p.setAttribute("aria-label",`${statusText(job.status)} ${p.value}%`);main.append(p);}if(job.error)main.append(node("p",typeof job.error==="string"?job.error:JSON.stringify(job.error),"job-error"));const actions=node("div",null,"row-actions");if(job.status==="failed")actions.append(button(t("retry"),async event=>{const retryButton=event.currentTarget;retryButton.disabled=true;try{await api(`/jobs/${pathId(job.id)}/retry`,{method:"POST",body:{}});notify(t("retryQueued"));await refreshDocuments();}catch(e){notify(e.message,true);retryButton.disabled=false;}}));row.append(main,actions);return row;}));}
  async function refreshTrackedJob() {
    const result = state.change?.result;
    const id = result?.job_id || result?.job?.id;
    if (id && !state.jobs.some(job => job.id === id)) {
      const job = await api(`/jobs/${pathId(id)}`);
      state.jobs.unshift(job.job || job);
    }
  }
  async function refreshDocuments() {
    if (!state.user) return;
    const results = await Promise.allSettled([
      api(`/policies?limit=${state.policyLimit}&offset=${state.policyOffset}`),
      api("/jobs")
    ]);
    const failures = [];
    results.forEach((result, index) => {
      if (result.status === "fulfilled") {
        if (index === 0) state.policies = array(result.value, "policies");
        else state.jobs = array(result.value, "jobs");
      } else if (result.reason.status !== 401) failures.push(result.reason);
    });
    if (state.user) await refreshTrackedJob();
    renderPolicies(); renderJobs(); renderChange();
    if (failures.length) throw failures[0];
  }
  async function loadPolicyPage(offset){if(state.busy.has("policy-page"))return;state.busy.add("policy-page");$("policies-previous").disabled=true;$("policies-next").disabled=true;try{const payload=await api(`/policies?limit=${state.policyLimit}&offset=${offset}`);state.policyOffset=offset;state.policies=array(payload,"policies");renderPolicies();}catch(e){notify(e.message,true);}finally{state.busy.delete("policy-page");renderPagination();}}
  function renderPagination(){$("policies-previous").textContent=t("previousPage");$("policies-next").textContent=t("nextPage");$("policies-page").textContent=t("pageCount",{page:Math.floor(state.policyOffset/state.policyLimit)+1,limit:state.policyLimit});$("policies-previous").disabled=state.policyOffset===0||state.busy.has("policy-page");$("policies-next").disabled=state.policies.length<state.policyLimit||state.busy.has("policy-page");}
  async function pollJobs() {
    if (!state.user || state.polling || !state.jobs.some(job => !finished(job.status))) return;
    state.polling = true;
    try {
      const prior = new Map(state.jobs.map(job => [job.id, job.status]));
      const result = await api("/jobs");
      state.jobs = array(result, "jobs");
      await refreshTrackedJob();
      renderJobs(); renderChange();
      if (state.jobs.some(job => finished(job.status) && prior.get(job.id) !== job.status)) {
        const policies = await api(`/policies?limit=${state.policyLimit}&offset=${state.policyOffset}`);
        state.policies = array(policies, "policies");
        renderPolicies();
      }
      state.lastPollError = false;
    } catch (error) {
      if (!state.lastPollError && error.status !== 401) {
        notify(t("refreshFailed"), true);
        state.lastPollError = true;
      }
    } finally { state.polling = false; }
  }
  function uploadFile(file,title,scope,replaces,current,total){return new Promise((resolve,reject)=>{const epoch=state.epoch;const xhr=new XMLHttpRequest();state.uploadXhr=xhr;xhr.open("POST","/api/v2/uploads");xhr.withCredentials=true;xhr.setRequestHeader("Accept","application/json");xhr.setRequestHeader("X-CSRF-Token",state.csrf);xhr.upload.onprogress=event=>{if(epoch!==state.epoch)return;const percent=event.lengthComputable?Math.round(event.loaded/event.total*100):0;$("upload-progress-name").textContent=t("uploading",{current,total,name:file.name});$("upload-progress-percent").textContent=`${percent}%`;$("upload-progress-bar").value=percent;if(percent===100)$("upload-progress-name").textContent=t("uploadWaiting");};xhr.onload=()=>{state.uploadXhr=null;if(epoch!==state.epoch){reject(new Error(t("sessionChanged")));return;}let payload={};try{payload=JSON.parse(xhr.responseText);}catch{/* The HTTP status remains authoritative. */}if(xhr.status>=200&&xhr.status<300)resolve(payload);else{const error=new Error(detailMessage(payload,t("requestFailed",{status:xhr.status})));error.status=xhr.status;if(xhr.status===401){showLogin();notify(t("sessionExpired"),true);}reject(error);}};xhr.onerror=()=>{state.uploadXhr=null;reject(new Error(t("networkError")));};xhr.onabort=()=>{state.uploadXhr=null;reject(new Error(t("uploadCancelled")));};const form=new FormData();form.append("file",file);form.append("title",title);form.append("scope",scope);if(replaces)form.append("replaces",replaces);xhr.send(form);});}
  async function submitUpload(event){event.preventDefault();if(state.busy.has("upload")||!canManage())return;const files=[...state.files];if(!files.length){notify(t("chooseFiles"),true);return;}const replaces=$("upload-replaces").value;const policy=state.policies.find(p=>p.id===replaces);if(replaces&&files.length!==1){notify(t("replaceSingle"),true);return;}const scope=policy?.scope||(isAdmin()?$("upload-scope-admin").value.trim():$("upload-scope").value);if(!scope){notify(t("chooseScope"),true);return;}if(!isAdmin()&&!state.user.scopes.includes(scope)){notify(t("scopeInvalid"),true);return;}const limit=Number(state.limits.max_upload_bytes)||104857600;for(const file of files){if(file.size>limit){notify(t("tooLarge",{name:file.name,size:bytes(limit)}),true);return;}if(!/\.(pdf|docx|pptx|xlsx|html|txt|md)$/i.test(file.name)){notify(t("unsupported",{name:file.name}),true);return;}}const epoch=state.epoch;busy("upload",true);$("upload-progress").hidden=false;let count=0;const errors=[];try{for(let i=0;i<files.length;i++){if(epoch!==state.epoch)break;$("upload-progress-bar").value=0;$("upload-progress-percent").textContent="0%";$("upload-progress-name").textContent=t("uploading",{current:i+1,total:files.length,name:files[i].name});const title=((files.length===1?$("upload-title").value.trim():"")||files[i].name.replace(/\.[^.]+$/,"")).slice(0,200);try{await uploadFile(files[i],title,scope,replaces,i+1,files.length);count++;await refreshDocuments();}catch(e){errors.push(`${files[i].name}: ${e.message}`);if(e.status===401||epoch!==state.epoch)break;}}if(epoch===state.epoch){if(errors.length)notify(`${t("uploaded",{count})}\n${t("uploadFailures",{count:errors.length})} ${errors.join("; ")}`,true);else notify(t("uploaded",{count}));state.files=files.filter(file=>errors.some(e=>e.startsWith(`${file.name}:`)));$("upload-files").value="";$("upload-title").value="";renderFiles();}}finally{busy("upload",false);$("upload-progress").hidden=true;renderFiles();}}

